+/** Picks `en` or `ko` from an Accept-Language header (q-values, region tags), else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const ranked = String(header ?? "")
+    .split(",")
+    .map((part, i) => {
+      const [tag, ...params] = part.trim().split(";");
+      const q = params.map((p) => p.trim()).find((p) => /^q=/i.test(p));
+      const weight = q === undefined ? 1 : Number(q.slice(2));
+      return { lang: tag.trim().toLowerCase().split("-")[0], weight, i };
+    })
+    .filter((x) => x.weight > 0 && (x.lang === "en" || x.lang === "ko"))
+    .sort((a, b) => b.weight - a.weight || a.i - b.i);
+  return ranked.length ? ranked[0].lang : fallback;
+}
+
 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
